def norm(x):
    if x is None:
        return ""
    return str(x).strip().lower()

def matches(req, opt):
    r = norm(req)
    o = norm(opt)
    if not r or not o:
        return False
    if r == o or r in o or o in r:
        return True
    r2 = r.replace(" ", "").replace("-", "").replace("_", "")
    o2 = o.replace(" ", "").replace("-", "").replace("_", "")
    if r2 and (r2 == o2 or r2 in o2 or o2 in r2):
        return True
    return False

def choose_option(reqs, clickables):
    for req in reqs:
        if norm(req):
            for opt in clickables:
                if matches(req, opt):
                    return opt
    return ""

def hook(ctx, nb):
    try:
        action = ctx["action"]
        state = ctx["state"]
        preds = ctx["predicates"]
        task = ctx["task"]
        tool = action["tool"]
        val = norm(action["value_normalized"])
        if tool != "click_action" or val != "buy now":
            return None
        if preds["product_price_over_budget"]:
            return {"kind": "block_and_prompt", "message": "Do not buy this item: its current price is over the task budget. Go back to search/results and choose an in-budget product or variant."}
        if preds["required_options_unselected"]:
            clickables = state["clickables"]
            reqs = [task["required_color"], task["required_size"], task["required_material"]]
            opt = choose_option(reqs, clickables)
            if opt:
                return {"kind": "rewrite_action", "action": opt, "message": "Select the required visible option before using Buy Now."}
            return {"kind": "block_and_prompt", "message": "A required product option is still unselected. Select the matching visible color, size, or material before Buy Now; if no matching option exists, go back to search/results."}
    except Exception:
        return None
    return None
